"""Experiments for the imperative-to-Horn clause translator.

Five small programs -- a counter, a sum accumulator, a branch, an unsafe loop
and a straight line arithmetic block -- are translated into constrained Horn
clauses and discharged with Spacer.  Four of them are safe, the loop that
increments past its assertion bound is not.
"""

import time

from framework import report_result
from verification.horn_translator import HornVerifier

#: The programs to translate, as ``(name, source)`` pairs.
PROGRAMS = [
    ("counter", """
// count up to ten, then check where the loop left off
var x = 0;
while (x < 10) {
    x = x + 1;
}
assert(x == 10);
"""),
    ("sum", """
var s = 0;
var i = 0;
while (i < 5) {
    s = s + i;
    i = i + 1;
}
assert(s >= 0);
"""),
    ("branch", """
var x = 5;
if (x > 3) {
    x = x - 1;
} else {
    x = x + 1;
}
assert(x >= 0);
"""),
    ("unsafe", """
// leaves the loop at x == 100, so the assertion below fails
var x = 0;
while (x < 100) {
    x = x + 2;
}
assert(x < 50);
"""),
    ("arith", """
var a = 1;
var b = 2;
a = a + b;
b = a * 2;
assert(b == 6);
"""),
]


def run_horn_experiments():
    """Translate and verify every program in :data:`PROGRAMS`, reporting metrics."""
    verifier = HornVerifier()
    results = [verifier.verify(source) for _, source in PROGRAMS]

    report_result("HORN_CLAUSES_GENERATED",
                  sum(result["num_clauses"] for result in results))
    report_result("HORN_PROGRAMS_VERIFIED",
                  sum(1 for result in results if result["safe"]))
    report_result("HORN_PROGRAMS_UNSAFE",
                  sum(1 for result in results if result["status"] == "unsafe"))
    report_result("HORN_LOOP_INVARIANTS",
                  sum(len(result["invariants"]) for result in results))

    # Time the translation on its own -- parsing, Horn encoding and building
    # the Fixedpoint rules -- so the Spacer queries above stay out of it.
    started = time.time()
    for _, source in PROGRAMS:
        verifier.translate(source)
    report_result("HORN_TRANSLATION_TIME", "%.2f" % (time.time() - started))


if __name__ == "__main__":
    run_horn_experiments()
